namespace Lustral;

/// <summary>The scripting backend of a Unity game.</summary>
public enum ScriptingBackend
{
    /// <summary>Mono: the game's scripts are .NET assemblies in <c>&lt;game&gt;_Data/Managed</c>.</summary>
    Mono,

    /// <summary>IL2CPP: the game's scripts are compiled to native code in <c>GameAssembly.dll</c>. Mods reference interop assemblies generated by Lustral.</summary>
    Il2Cpp,
}

/// <summary>Information about the running game, as reported by the game itself. Lustral reads it from the game's files before any mod loads.</summary>
public sealed class GameInfo
{
    internal GameInfo(string name, string? developer, string? version, string? unityVersion, ScriptingBackend backend, string directory)
    {
        Name = name;
        Developer = developer;
        Version = version;
        UnityVersion = unityVersion;
        Backend = backend;
        Directory = directory;
    }

    /// <summary>The game's name (<c>Application.productName</c>), for example <c>Lethal Company</c>.</summary>
    public string Name { get; }

    /// <summary>The game's developer (<c>Application.companyName</c>), or null if not set.</summary>
    public string? Developer { get; }

    /// <summary>
    /// The game's version (<c>Application.version</c>), for example <c>1.2.0</c>. Some games display a different version
    /// to players. Null if Lustral cannot read the version from the game's files, which can occur with Unity versions newer
    /// than Lustral supports; the version is then read once the game is running (by <see cref="Mod.OnGameReady"/>) and
    /// stored for subsequent launches.
    /// </summary>
    public string? Version { get; internal set; }

    /// <summary>The Unity version the game was built with, for example <c>2022.3.62f2</c>, or null if unknown.</summary>
    public string? UnityVersion { get; }

    /// <summary>The game's scripting backend.</summary>
    public ScriptingBackend Backend { get; }

    /// <summary>The absolute path of the game's folder, which contains its executable.</summary>
    public string Directory { get; }

    /// <summary>Returns a description such as <c>Lethal Company 0.1 (Unity 2022.3.62f2, Mono)</c>.</summary>
    public override string ToString() =>
        $"{Name}{(Version is null ? "" : " " + Version)} (Unity {UnityVersion ?? "unknown"}, {(Backend == ScriptingBackend.Il2Cpp ? "IL2CPP" : "Mono")})";
}
